sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({ api, event, helpers, imports }) {
    try {
        // Retrieve the current state of buttonTracker or initialize it
        console.log("Button Data",api.data.mark_walk_btn_2.output.buttonData)
        let currentState = api.state["buttonTracker"] || {};

        // Toggle the state of the button
        currentState[event.elementId] = currentState[event.elementId] === 1 ? 0 : 1;

        // Update the state
        api.setState("buttonTracker", currentState);

        // Log the updated state
        console.log("Updated buttonTracker state:", currentState);

        // Retrieve the button label associated with the event
        const buttonLabel = event.elementId; // Assuming `elementId` corresponds to `u_button_label`

        // Prepare the updated value for `u_read_flag`
        const updatedReadFlag = currentState[event.elementId] === 1 ? true : false;

        console.log(`Updating u_read_flag for button '${buttonLabel}' to ${updatedReadFlag}`);

        // Validate helpers.snHttp
        if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
            console.error("Error: helpers.snHttp is not properly initialized or callable.");
            return;
        }

        // Prepare the API request payload
        const requestData = {
            u_button_label: buttonLabel,
            u_read_flag: updatedReadFlag
        };

        try {
            // Make the HTTP POST request to update the table
            const response = await helpers.snHttp("/api/985627/buttonwalk", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(requestData)
            });

            // Handle the response
            if (response.status === 200) {
                console.log(`Button '${buttonLabel}' updated successfully in the table.`, response.result);
            } else {
                console.error(`Failed to update button '${buttonLabel}' in the table:`, response);
            }
        } catch (httpError) {
            console.error(`Error updating button '${buttonLabel}' in the table:`, httpError);
        }
    } catch (error) {
        console.error("Unexpected error in handler:", error);
    }



    api.setState('refresh',{timestamp: Date.now()})
            api.data.mark_walk_btn_2.refresh().then(() => {
        console.log('Custom data source refreshed successfully.');
    }).catch((error) => {
        console.error('Error refreshing custom data source:', error);
    });

}
